import java.util.*;

import jakarta.validation.*;
import jakarta.validation.constraints.*;

public class Main {
    static final Validator VALIDATOR = Validation.buildDefaultValidatorFactory().getValidator();

    public static void main(String[] args) {
        TodoService service = new TodoService(VALIDATOR);
        try {
            service.tambah(new TodoBaru("", 5));
            System.out.println("Tersimpan");
        } catch (ConstraintViolationException e) {
            System.out.println("Ditolak: " + e.getConstraintViolations().size());
        }
        System.out.println("Jumlah todo: " + service.semua().size());
    }
}

class TodoBaru {
    @NotBlank(message = "Judul wajib diisi")
    @Size(max = 50, message = "Judul maksimal {max} huruf")
    String judul;

    @Min(value = 1, message = "Prioritas minimal {value}")
    @Max(value = 3, message = "Prioritas maksimal {value}")
    int prioritas;

    TodoBaru(String judul, int prioritas) {
        this.judul = judul;
        this.prioritas = prioritas;
    }
}

class Todo {
    private final int id;
    private final String judul;
    private final int prioritas;

    Todo(int id, String judul, int prioritas) {
        this.id = id;
        this.judul = judul;
        this.prioritas = prioritas;
    }

    @Override
    public String toString() {
        return id + ". " + judul + " (P" + prioritas + ")";
    }
}

class TodoService {
    private final Validator validator;
    private final List<Todo> data = new ArrayList<>();

    TodoService(Validator validator) {
        this.validator = validator;
    }

    Todo tambah(TodoBaru baru) {
        Set<ConstraintViolation<TodoBaru>> salah = validator.validate(baru);
        if (!salah.isEmpty()) {
            throw new ConstraintViolationException(salah);
        }
        Todo t = new Todo(data.size() + 1, baru.judul.trim(), baru.prioritas);
        data.add(t);
        return t;
    }

    List<Todo> semua() {
        return data;
    }
}

